const copy = <T>(v: T): T => structuredClone(v);
function setup(principalActor = captured.fabric.executeResponse.result.actorId) {
  const values = new Map<string,string>(); const storage = { getItem: (key: string) => values.get(key) ?? null, setItem: (key: string,v: string) => { values.set(key,v); }, removeItem: (key: string) => { values.delete(key); } };
  let actor = principalActor, generation = 'a', endpoint = '/api', invalidate = () => {};
  const transport = vi.fn(), uuid = vi.fn(); const principal = () => ({ actorId: actor, endpoint, generation, headers: { Authorization: 'Bearer private' } });
  const adapter = createDevelopmentConversionUiService({ principal, storage, fetch: transport as any, uuid, subscribe: f => { invalidate = f; return () => {}; } });
  const response = (result: unknown) => ({ ok: true, json: async () => ({ ok: true, result }) });
  return { adapter, values, storage, principal, transport, uuid, response, invalidate, switchAccount: () => { actor = 'other'; generation = 'next'; invalidate(); }, switchEndpoint: () => { endpoint = '/other'; generation = 'next'; invalidate(); } };
}
const fields = (family: 'fabric' | 'garment') => developmentConversionOriginalFields(captured[family].executeRequest as any);
async function prepare(f: ReturnType<typeof setup>, family: 'fabric' | 'garment') {
  const wire = captured[family], input = wire.executeRequest; f.adapter.open(input.source.id); f.transport.mockResolvedValueOnce(f.response(wire.contextResponse.result)); await f.adapter.prepare(input.source.id, input.parameters.selectedSource as any); f.uuid.mockReturnValueOnce(input.requestKey); return input.source.id;
}
describe('existing-modal conversion adapter', () => {
  it.each(['fabric', 'garment'] as const)('keeps native %s selection, factory and exact string input', async family => {
    const f = setup(), sourceId = await prepare(f, family); f.transport.mockResolvedValueOnce(f.response(captured[family].executeResponse.result));
    await expect(f.adapter.submit(sourceId, fields(family))).resolves.toMatchObject({ outcome: 'converted' });
    const body = JSON.parse(f.transport.mock.calls[1][1].body); expect(body).toEqual(captured[family].executeRequest); expect(body.parameters.selectedSource.type).not.toBe('Asset'); expect(typeof body.parameters.quantity).toBe('string'); expect(f.adapter.pending(sourceId)).toBeNull();
  });
  it('close and reopen retain original input; edited draft cannot replace the retry body/key', async () => {
    const f = setup(), sourceId = await prepare(f, 'fabric'); f.transport.mockRejectedValueOnce(new Error('lost')); await expect(f.adapter.submit(sourceId, fields('fabric'))).rejects.toThrow();
    f.adapter.close(); const opened = f.adapter.open(sourceId); expect(opened.session.fields).toEqual(fields('fabric')); expect(opened.session.original).toEqual(captured.fabric.executeRequest);
    f.transport.mockResolvedValueOnce(f.response(captured.fabric.recoverResponse.result)); await f.adapter.submit(sourceId, { ...fields('fabric'), quantity: '999' });
    expect(JSON.parse(f.transport.mock.calls[2][1].body)).toEqual(captured.fabric.executeRequest); expect(f.transport.mock.calls[2][0]).toMatch(/recover$/); expect(f.uuid).toHaveBeenCalledTimes(1);
  });
  it('closing while execute is in flight cannot clear pending from a late ACK', async () => {
    const f = setup(), sourceId = await prepare(f, 'fabric'); let resolve: any; f.transport.mockImplementationOnce(() => new Promise(r => { resolve = r; })); const work = f.adapter.submit(sourceId, fields('fabric')); f.adapter.close(); resolve(f.response(captured.fabric.executeResponse.result));
    await expect(work).rejects.toMatchObject({ code: 'STALE_CONTEXT' }); expect(f.adapter.pending(sourceId)).toEqual(captured.fabric.executeRequest);
    f.adapter.open(sourceId); f.transport.mockResolvedValueOnce(f.response(captured.fabric.recoverResponse.result)); await expect(f.adapter.recover(sourceId)).resolves.toMatchObject({ outcome: 'converted' });
  });
  it('new service after refresh reads original session pending, without resetting the key', async () => {
    const f = setup(), sourceId = await prepare(f, 'garment'); f.transport.mockRejectedValueOnce(new Error('lost')); await expect(f.adapter.submit(sourceId, fields('garment'))).rejects.toThrow(); f.adapter.dispose();
    const next = createDevelopmentConversionUiService({ principal: f.principal, storage: f.storage, fetch: f.transport as any }); next.open(sourceId); expect(next.pending(sourceId)).toEqual(captured.garment.executeRequest);
    f.transport.mockResolvedValueOnce(f.response(captured.garment.recoverResponse.result)); await expect(next.recover(sourceId)).resolves.toMatchObject({ outcome: 'converted' });
  });
  it('an unrelated source proceeds while the previous source retains unresolved pending', async () => {
    const f = setup(), first = await prepare(f, 'fabric'); f.transport.mockRejectedValueOnce(new Error('lost')); await expect(f.adapter.submit(first, fields('fabric'))).rejects.toThrow();
    const second = await prepare(f, 'garment'); f.transport.mockResolvedValueOnce(f.response(captured.garment.executeResponse.result)); await expect(f.adapter.submit(second, fields('garment'))).resolves.toMatchObject({ outcome: 'converted' });
    expect(f.adapter.pending(first)).toEqual(captured.fabric.executeRequest); expect(f.adapter.pending(second)).toBeNull(); expect(f.values.size).toBe(1);
  });
  it.each(['account', 'endpoint', 'ABA', 'source'])('fences late %s completion and retains old original namespace', async mode => {
    const f = setup(), sourceId = await prepare(f, 'fabric'); let resolve: any; f.transport.mockImplementationOnce(() => new Promise(r => { resolve = r; })); const work = f.adapter.submit(sourceId, fields('fabric'));
    if (mode === 'account') f.switchAccount(); if (mode === 'endpoint') f.switchEndpoint(); if (mode === 'ABA') f.invalidate(); if (mode === 'source') f.adapter.open(captured.garment.executeRequest.source.id);
    resolve(f.response(captured.fabric.executeResponse.result)); await expect(work).rejects.toMatchObject({ code: 'STALE_CONTEXT' }); expect(f.values.size).toBe(1);
  });
  it('a slow earlier preparation cannot override a newer selected source context', async () => {
    const f = setup(), sourceId = captured.fabric.executeRequest.source.id; f.adapter.open(sourceId); let resolve: any; f.transport.mockImplementationOnce(() => new Promise(r => { resolve = r; })); const first = f.adapter.prepare(sourceId, captured.fabric.executeRequest.parameters.selectedSource as any);
    const secondContext: any = copy(captured.fabric.contextResponse.result); f.transport.mockResolvedValueOnce(f.response(secondContext)); const second = f.adapter.prepare(sourceId, captured.fabric.executeRequest.parameters.selectedSource as any); await second;
    resolve(f.response(captured.fabric.contextResponse.result)); await expect(first).rejects.toMatchObject({ code: 'STALE_CONTEXT' }); expect(f.adapter.session(sourceId)?.prepared).toEqual(secondContext);
  });
  it('requires a prepared context and exact selected factory before generating a key or writing', async () => {
    const f = setup(), id = captured.fabric.executeRequest.source.id; f.adapter.open(id); await expect(f.adapter.submit(id, fields('fabric'))).rejects.toMatchObject({ code: 'CONTEXT_NOT_READY' }); expect(f.uuid).not.toHaveBeenCalled();
    await prepare(f, 'fabric'); await expect(f.adapter.submit(id, { ...fields('fabric'), millSupplierId: 'wrong' })).rejects.toMatchObject({ code: 'PREPARATION_CHANGED' }); expect(f.transport).toHaveBeenCalledTimes(1);
  });
  it('corrupt same-source cache is blocked and is never treated as empty', async () => {
    const f = setup(), sourceId = await prepare(f, 'fabric'); f.transport.mockRejectedValueOnce(new Error('lost')); await expect(f.adapter.submit(sourceId, fields('fabric'))).rejects.toThrow(); const key = [...f.values.keys()][0]; f.values.set(key, '{broken'); f.adapter.close(); expect(() => f.adapter.open(sourceId)).toThrow(expect.objectContaining({ code: 'CORRUPT_PENDING' }));
  });
  it('supports the verified link preparation and restores pending original target after close', async () => {
    const f = setup(link.executeResponse.result.actorId), sourceId = link.executeRequest.source.id; f.adapter.open(sourceId); f.transport.mockResolvedValueOnce(f.response(link.contextResponse.result)); await f.adapter.prepare(sourceId, link.executeRequest.parameters.selectedSource as any, link.executeRequest.parameters.orderId); f.uuid.mockReturnValueOnce(link.executeRequest.requestKey);
    f.transport.mockRejectedValueOnce(new Error('lost')); await expect(f.adapter.submit(sourceId, developmentConversionOriginalFields(link.executeRequest as any))).rejects.toThrow(); f.adapter.close(); expect(f.adapter.open(sourceId).session.original).toEqual(link.executeRequest);
    f.transport.mockResolvedValueOnce(f.response(link.recoverResponse.result)); await expect(f.adapter.cancelOriginal(sourceId)).resolves.toMatchObject({ outcome: 'linked' }); expect(f.adapter.pending(sourceId)).toBeNull();
  });
});
